(function(){function base64urlEncode(str){try{return btoa(unescape(encodeURIComponent(str))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"")}catch(e){return btoa(str).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"")}}function formatText(text){if(!text)return"";return text.replace(/\*(.*?)\*/g,"<mark>$1</mark>").replace(/<br\s*\/?>/gi,'<span style="display: block; margin-bottom: 0.5em;"></span>')}function ce(tag,className,html){const el=document.createElement(tag);if(className)el.className=className;if(html!==undefined)el.innerHTML=html;return el}window.updateExamplesWraps=function(){document.querySelectorAll(".example").forEach(function(ex){const fr=ex.querySelector(".example-fr");const ru=ex.querySelector(".example-ru");if(!fr||!ru||ex.offsetParent===null)return;ru.classList.remove("wrapped");const frRect=fr.getBoundingClientRect();const ruRect=ru.getBoundingClientRect();if(ruRect.bottom>frRect.bottom+5){ru.classList.add("wrapped")}})};window.addEventListener("resize",window.updateExamplesWraps);function renderExamples(examples){const container=ce("div","examples-list");examples.forEach(function(ex){const exampleEl=ce("div","example");const frSpan=ce("span","example-fr",formatText(ex.fr));const ruSpan=ce("span","example-ru",formatText(ex.ru));exampleEl.appendChild(frSpan);exampleEl.appendChild(ruSpan);container.appendChild(exampleEl);setTimeout(window.updateExamplesWraps,0)});return container}function renderMeaning(meaning,index){const el=ce("div","meaning");const inner=ce("div","meaning-inner");const descEl=ce("div","meaning-description");if(index!==undefined&&index!==null){const idxSpan=ce("span","meaning-index",index+".");descEl.appendChild(idxSpan)}const textSpan=ce("span","meaning-text",formatText(meaning.description||""));descEl.appendChild(textSpan);inner.appendChild(descEl);if(meaning.comment){inner.appendChild(ce("div","comment",formatText(meaning.comment)))}if(meaning.examples&&meaning.examples.length>0){inner.appendChild(renderExamples(meaning.examples))}el.appendChild(inner);return el}function renderSense(sense,parentTranslation){const el=ce("div","sense");const hasDistinctDesc=Boolean(sense.description&&sense.description.trim()!==parentTranslation.trim());if(hasDistinctDesc){el.appendChild(ce("div","sense-description",formatText(sense.description)))}if(sense.comment){el.appendChild(ce("div","comment",formatText(sense.comment)))}if(sense.examples&&sense.examples.length>0){el.appendChild(renderExamples(sense.examples))}if(!hasDistinctDesc){el.classList.add("sense-examples-only")}return el}function renderPhrase(item){const el=ce("div","phrase");const inner=ce("div","phrase-inner");const header=ce("div","phrase-header");header.appendChild(ce("span","phrase-fr",formatText(item.phrase)));header.appendChild(ce("span","phrase-translation","— "+formatText(item.translation)));inner.appendChild(header);if(item.comment){inner.appendChild(ce("div","comment",formatText(item.comment)))}if(item.senses&&item.senses.length>0){const sensesList=ce("div","senses-list");item.senses.forEach(function(sense){sensesList.appendChild(renderSense(sense,item.translation))});inner.appendChild(sensesList)}el.appendChild(inner);return el}function animateSectionScroll(parent,btn,isExpanding,hiddenHeight){const startTime=performance.now();const duration=500;let sectionTop=parent.getBoundingClientRect().top+window.pageYOffset;let sibling=parent.previousElementSibling;while(sibling){if(sibling.tagName==="H3"||sibling.tagName==="H2"||sibling.classList.contains("alert")){sectionTop=sibling.getBoundingClientRect().top+window.pageYOffset;break}sibling=sibling.previousElementSibling}let refElement=null;const firstHidden=parent.querySelector(".hidden-item");if(firstHidden){const allItems=Array.from(parent.querySelectorAll(".meaning, .group, .phrase-item, .phrase"));const idx=allItems.indexOf(firstHidden);if(idx>0){refElement=allItems[idx-1]}}if(!refElement){refElement=parent}let targetScrollYForCollapse=null;const hHeight=hiddenHeight||0;if(!isExpanding&&hHeight>0){const initialScrollY=window.pageYOffset;const btnInitialTop=btn.getBoundingClientRect().top;const btnAbsoluteY=btnInitialTop+initialScrollY;const finalBtnAbsoluteY=btnAbsoluteY-hHeight;const targetScreenTop=window.innerHeight/2;const desiredScrollY=finalBtnAbsoluteY-targetScreenTop;let targetScrollY=Math.max(desiredScrollY,sectionTop);if(targetScrollY<0){targetScrollY=0}if(targetScrollY<initialScrollY){targetScrollYForCollapse=targetScrollY}}const initialScrollYForAnimation=window.pageYOffset;function step(now){const elapsed=now-startTime;const progress=Math.min(elapsed/duration,1);const currentScrollY=window.pageYOffset;if(isExpanding){const refTop=refElement.getBoundingClientRect().top+window.pageYOffset;const btnCurrentY=btn.getBoundingClientRect().top+window.pageYOffset;const idealScrollY=btnCurrentY-window.innerHeight+btn.offsetHeight+20;const maxScrollY=refTop-10;const targetY=Math.min(idealScrollY,maxScrollY);if(targetY>currentScrollY){window.scrollTo(0,targetY)}}else{if(targetScrollYForCollapse!==null){const ease=1-Math.pow(1-progress,3);const nextScrollY=initialScrollYForAnimation+(targetScrollYForCollapse-initialScrollYForAnimation)*ease;window.scrollTo(0,nextScrollY)}}if(progress<1){requestAnimationFrame(step)}}requestAnimationFrame(step)}function renderExpandableList(container,items,title,containerClass,isCompact){if(!items||items.length===0)return;container.appendChild(ce("h3","",title));const listLimit=isCompact?8:4;const listThreshold=isCompact?9:6;const isCollapsedInit=items.length>listThreshold;const listContainer=ce("div",containerClass+(isCollapsedInit?" collapsed":""));let renderedCount=0;items.forEach(function(item){const itemEl=renderPhrase(item);if(isCollapsedInit&&renderedCount>=listLimit){itemEl.classList.add("hidden-item")}renderedCount++;listContainer.appendChild(itemEl)});container.appendChild(listContainer);if(isCollapsedInit){const remainingCount=items.length-listLimit;const btn=ce("div","show-more-btn","Показать еще "+remainingCount);btn.onclick=function(){const isExpanding=listContainer.classList.contains("collapsed");let hiddenHeight=0;if(!isExpanding){const hiddenItems=listContainer.querySelectorAll(".hidden-item");hiddenItems.forEach(function(item){hiddenHeight+=item.offsetHeight})}listContainer.classList.toggle("collapsed");btn.classList.toggle("expanded");btn.textContent=isExpanding?"Свернуть":"Показать еще "+remainingCount;animateSectionScroll(listContainer,btn,isExpanding,hiddenHeight)};container.appendChild(btn)}}const STORAGE_KEY="dict_compact_view";function getCompactMode(){try{const saved=localStorage.getItem(STORAGE_KEY);if(saved===null){return true}return saved==="true"}catch(e){return true}}function setCompactMode(val){try{localStorage.setItem(STORAGE_KEY,val?"true":"false")}catch(e){}}function toggleCompactMode(){const nextMode=!getCompactMode();setCompactMode(nextMode);document.querySelectorAll(".dictionnaire").forEach(function(c){if(c._dictData){renderDictionary(c,c._dictData,c._dictVerbId)}})}function hasExamplesOrComments(data){if(!data)return false;if(data.comment)return true;if(data.groups){for(let i=0;i<data.groups.length;i++){const g=data.groups[i];if(g.meanings){for(let j=0;j<g.meanings.length;j++){const m=g.meanings[j];if(m.comment||m.examples&&m.examples.length>0)return true}}}}if(data.meanings){for(let j=0;j<data.meanings.length;j++){const m=data.meanings[j];if(m.comment||m.examples&&m.examples.length>0)return true}}if(data.phrases){for(let i=0;i<data.phrases.length;i++){const p=data.phrases[i];if(p.comment)return true;if(p.senses){for(let j=0;j<p.senses.length;j++){const s=p.senses[j];if(s.comment||s.examples&&s.examples.length>0)return true}}}}if(data.idioms){for(let i=0;i<data.idioms.length;i++){const p=data.idioms[i];if(p.comment)return true;if(p.senses){for(let j=0;j<p.senses.length;j++){const s=p.senses[j];if(s.comment||s.examples&&s.examples.length>0)return true}}}}return false}function renderDictionary(container,data,verbId){container.innerHTML="";const isMobile=container.closest(".translation_mobile")!==null;const hasTranslations=data.groups&&data.groups.length>0||data.phrases&&data.phrases.length>0||data.idioms&&data.idioms.length>0;const verbUpper=data.verb.toUpperCase();const titleText=data.verb.length<=15?"Перевод глагола "+verbUpper:"Перевод "+verbUpper;container.appendChild(ce("h2","",titleText));const hasDetails=hasExamplesOrComments(data);const isCompact=hasDetails&&getCompactMode();if(isCompact){container.classList.add("compact-view")}else{container.classList.remove("compact-view")}if(hasDetails){const toggleBtn=ce("button","dict-toggle-btn "+(isCompact?"compact":"expanded"));toggleBtn.type="button";const iconSpan=ce("span","dict-toggle-icon",isCompact?"💡":"✕");const textSpan=ce("span","dict-toggle-text",isCompact?"Показать примеры и пояснения":"Скрыть примеры и пояснения");toggleBtn.appendChild(iconSpan);toggleBtn.appendChild(textSpan);toggleBtn.onclick=function(){toggleCompactMode()};container.appendChild(toggleBtn)}if(data.moderationStatus==="draft"||data.moderationStatus==="pending"){const noticeAlert=ce("div","alert alert-light","");noticeAlert.style.padding="8px 12px";noticeAlert.style.marginBottom="15px";noticeAlert.style.border="1px solid #ddd";noticeAlert.style.backgroundColor="#f8f9fa";const noticeText=document.createTextNode("Этот раздел нам помогают создавать участники сообщества, он может содержать неточности. Заметили ошибку? ");const noticeLink=ce("a","","Помогите ее исправить!");const encodedVerbIdForLink=base64urlEncode(verbId);noticeLink.href="https://coverbe.web.app/"+encodedVerbIdForLink;noticeLink.target="_blank";noticeAlert.appendChild(noticeText);noticeAlert.appendChild(noticeLink);container.appendChild(noticeAlert)}let totalMeanings=0;if(data.groups&&data.groups.length>0){data.groups.forEach(function(g){if(g.meanings)totalMeanings+=g.meanings.length})}else if(data.meanings){totalMeanings=data.meanings.length}const meaningsLimit=isCompact?8:4;const meaningsThreshold=isCompact?9:5;let meaningsParent=container;let isMeaningsCollapsed=false;let remainingMeanings=0;if(totalMeanings>meaningsThreshold){isMeaningsCollapsed=true;remainingMeanings=totalMeanings-meaningsLimit;meaningsParent=ce("div","meanings-container collapsed")}let renderedCount=0;if(data.groups&&data.groups.length>0){const hasAnyGroupWithMultiple=Boolean(data.groups.some(function(g){return g.meanings&&g.meanings.length>1}));data.groups.forEach(function(group){const groupEl=ce("div","group");const groupInner=ce("div","group-inner");const hasHeader=group.romanNumeral&&String(group.romanNumeral).trim()!==""||group.title&&String(group.title).trim()!=="";if(hasHeader){const header=ce("div","group-header");const headerInner=ce("div","group-header-inner");if(group.romanNumeral){headerInner.appendChild(ce("span","roman-numeral",group.romanNumeral))}if(group.title){headerInner.appendChild(ce("span","group-title",formatText(group.title)))}header.appendChild(headerInner);groupInner.appendChild(header)}else{groupEl.classList.add("no-header")}let groupFullyHidden=true;if(group.meanings&&group.meanings.length>0){const meaningsList=ce("div","meanings-list");const shouldNumber=hasAnyGroupWithMultiple||group.meanings.length>1;group.meanings.forEach(function(m,idx){const mEl=renderMeaning(m,shouldNumber?idx+1:null);if(isMeaningsCollapsed&&renderedCount>=meaningsLimit){mEl.classList.add("hidden-item")}else{groupFullyHidden=false}meaningsList.appendChild(mEl);renderedCount++});groupInner.appendChild(meaningsList)}groupEl.appendChild(groupInner);if(isMeaningsCollapsed&&groupFullyHidden){groupEl.classList.add("hidden-item")}meaningsParent.appendChild(groupEl)})}else if(data.meanings&&data.meanings.length>0){const flatList=ce("div","meanings-list flat");const hasMultiple=data.meanings.length>1;data.meanings.forEach(function(m,idx){const mEl=renderMeaning(m,hasMultiple?idx+1:null);if(isMeaningsCollapsed&&renderedCount>=meaningsLimit){mEl.classList.add("hidden-item")}flatList.appendChild(mEl);renderedCount++});meaningsParent.appendChild(flatList)}if(isMeaningsCollapsed){container.appendChild(meaningsParent);const btn=ce("div","show-more-btn","Показать еще "+remainingMeanings);btn.onclick=function(){const isExpanding=meaningsParent.classList.contains("collapsed");let hiddenHeight=0;if(!isExpanding){const hiddenItems=meaningsParent.querySelectorAll(".hidden-item");hiddenItems.forEach(function(item){hiddenHeight+=item.offsetHeight})}meaningsParent.classList.toggle("collapsed");btn.classList.toggle("expanded");btn.textContent=isExpanding?"Свернуть":"Показать еще "+remainingMeanings;animateSectionScroll(meaningsParent,btn,isExpanding,hiddenHeight)};container.appendChild(btn)}renderExpandableList(container,data.phrases,"Фразеология","phrases-container",isCompact);renderExpandableList(container,data.idioms,"Идиоматические выражения","idioms-container",isCompact);if(data.comment){const commentEl=ce("div","verb-article-comment",formatText(data.comment));container.appendChild(commentEl)}}async function init(){const containers=document.querySelectorAll(".dictionnaire");if(containers.length===0)return;containers.forEach(async function(container){let verbId=container.getAttribute("data-verb");if(!verbId){const urlParams=new URLSearchParams(window.location.search);verbId=urlParams.get("verb")}if(!verbId){try{const configRes=await fetch("/api/config/verb");if(configRes.ok){const configData=await configRes.json();if(configData.verbId){verbId=configData.verbId}}}catch(e){console.log("Dictionary Module: Could not fetch verb from server config, falling back.")}}if(!verbId){verbId="etre"}container.innerHTML='<div class="loading">Загрузка статьи...</div>';const encodedVerbId=base64urlEncode(verbId);const hideUI=()=>{container.innerHTML=""};const apiBase=container.getAttribute("data-api-base")||"/api/";const apiUrl=apiBase.endsWith("/")?apiBase+encodedVerbId:apiBase+"/"+encodedVerbId;console.log("Dictionary Module: Fetching verb via: "+apiUrl);const controller=new AbortController;const timeoutId=setTimeout(function(){console.log("Dictionary Module: Request timed out");controller.abort()},1e4);try{const response=await fetch(apiUrl,{method:"GET",headers:{Accept:"application/json"},signal:controller.signal});clearTimeout(timeoutId);console.log("Dictionary Module: API Response Status:",response.status);if(response.status===200){const data=await response.json();container._dictData=data;container._dictVerbId=verbId;renderDictionary(container,data,verbId)}else{hideUI()}}catch(error){clearTimeout(timeoutId);console.error("Dictionary Module: Fetch failed",error);hideUI()}})}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}})();